using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RegionalWeatherTests
{
 static WorldSession Start(){var setup=NewGameWorldTests.Setup([NewGameWorldTests.Officer("created:weather-lord",StartTemplate.Daimyo,"site:nejo")],[new("created:weather-lord","created:weather-house",["site:nejo"],false)]);return new(NewGameWorld.Create(setup.World,setup.Registered,"created:weather-lord",20261022,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseSuccession.Policy,weatherPolicy:RegionalWeather.Policy));}
 [Fact]public void WeatherIsReproducibleAndOldWorldUnchanged(){var old=HouseholdCourtTests.Start();var raw=ContractJson.Write(old.DiagnosticSnapshot());Assert.Empty(RegionalWeather.Events(old.DiagnosticSnapshot(),new("site:nejo"),365*86400));Assert.Equal(raw,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(raw)).DiagnosticSnapshot()));var w=Start().DiagnosticSnapshot();Assert.Equal(ContractJson.Write(RegionalWeather.Events(w,new("site:nejo"),365*86400)),ContractJson.Write(RegionalWeather.Events(ContractJson.Copy(w),new("site:nejo"),365*86400)));}
 [Fact]public void DamageRemainsUntilRealRepairAndMidSaveHasSameFuture(){var s=Start();var w=s.DiagnosticSnapshot();var site=new EntityId("site:nejo");var disaster=RegionalWeather.Events(w,site,5*365*86400L).First(e=>e.Fields>0);NewGameWorldTests.At(s,disaster.At);Assert.True(RegionalWeather.Damage(s.DiagnosticSnapshot(),site,WorksKind.RepairFields,s.Seconds,s.Revision+1)>0);var input=new WorksInput(new("request:weather-repair"),site,WorksKind.RepairFields);var result=s.StartPublicWork(input,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);NewGameWorldTests.At(s,disaster.At+3*86400);s.SetPaused(true);var restored=new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(s.DiagnosticSnapshot())));foreach(var x in new[]{s,restored})NewGameWorldTests.At(x,disaster.At+7*86400);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));Assert.Equal(0,RegionalWeather.Damage(s.DiagnosticSnapshot(),site,WorksKind.RepairFields,s.Seconds,s.Revision+1));Assert.Equal(ResultCode.AlreadyAccepted,s.StartPublicWork(input,s.Revision).Code);}
 [Fact]public void LocalViewDoesNotRevealOtherPlaces(){var s=Start();NewGameWorldTests.At(s,12*86400);Assert.All(RegionalWeather.LocalEvents(s.DiagnosticSnapshot(),s.PlayerControl),e=>Assert.Equal(new EntityId("site:nejo"),e.Site));}
 [Fact]public void SnowAndTyphoonRespectRegionsAndSeasons(){var w=Start().DiagnosticSnapshot();foreach(var site in NationalRoutes.Sites.Select(s=>s.Id)){foreach(var e in RegionalWeather.Events(w,site,3*365*86400L)){var date=DateOnly.Parse(w.EpochDate).AddDays((int)(e.At/86400));if(e.Kind=="大雪"){Assert.True(RegionalWeather.North(site));Assert.Equal(1,date.Month);}if(e.Kind=="台風"){Assert.True(RegionalWeather.West(site));Assert.Equal(9,date.Month);}}}}
 [Fact]public void FieldDamageChangesHarvestFactorAndRepairConsumesRealResources(){var s=Start();var site=new EntityId("site:nejo");var e=RegionalWeather.Events(s.DiagnosticSnapshot(),site,365*86400).First(e=>e.Fields>0);NewGameWorldTests.At(s,e.At);var w=s.DiagnosticSnapshot();int before=RegionalWeather.HarvestFactor(w,site,1560,s.Seconds,s.Revision+1);long cash=s.HouseTreasuryView()!.HouseCash,rice=s.CommunityEconomyView()!.Accounts.HouseRice;Assert.Equal(ResultCode.Accepted,s.StartPublicWork(new(new("request:weather-cost"),site,WorksKind.RepairFields),s.Revision).Code);Assert.Equal(cash-50,s.HouseTreasuryView()!.HouseCash);Assert.Equal(rice-100,s.CommunityEconomyView()!.Accounts.HouseRice);NewGameWorldTests.At(s,e.At+7*86400);Assert.True(RegionalWeather.HarvestFactor(s.DiagnosticSnapshot(),site,1560,s.Seconds,s.Revision+1)>before);}
}
